import { api, ApiError } from "@/lib/api-client";

const XLSX_CONTENT_TYPE =
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

export type EvaluationReportCategory = {
  id: number;
  name: string;
};

/**
 * Excel of the evaluation report of one category, generated by the backend
 * (GET /events/:eventId/reports/evaluation, permission read:grades). The file
 * already has the approved format, including co-winners sharing a position.
 */
export const getEvaluationReport = ({
  eventId,
  categoryId,
}: {
  eventId: number;
  categoryId: number;
}) => {
  return api.download(`/events/${eventId}/reports/evaluation`, {
    params: { categoryId },
    headers: { Accept: XLSX_CONTENT_TYPE },
    // The button shows its own message
    suppressErrorNotification: true,
  });
};

/** Fallback when the backend does not send Content-Disposition */
export const getEvaluationReportFallbackName = (
  eventId: number,
  categoryId: number,
) => `reporte_evaluacion_evento_${eventId}_categoria_${categoryId}.xlsx`;

export const saveFile = (blob: Blob, fileName: string) => {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
};

export const downloadEvaluationReport = async ({
  eventId,
  categoryId,
}: {
  eventId: number;
  categoryId: number;
}) => {
  const { blob, fileName } = await getEvaluationReport({ eventId, categoryId });
  saveFile(
    blob,
    fileName ?? getEvaluationReportFallbackName(eventId, categoryId),
  );
};

/** Message for the user from an error of the report endpoint */
export const getEvaluationReportErrorMessage = (error: unknown) => {
  if (error instanceof ApiError) {
    switch (error.status) {
      case 403:
        return "No tienes permiso para descargar este reporte.";
      case 404:
        return "No encontramos el evento o la categoría del reporte.";
    }
  }
  return "No se pudo descargar el reporte. Intenta de nuevo.";
};
